import { receptionist } from "@/content/receptionist";
import { services } from "@/content/services";

/**
 * The Retell agent, generated from content so the prompt and the server can't
 * drift apart: the tool names the prompt mentions are the ones `tools.ts`
 * answers. Paste into Retell (Agent → Single Prompt, Custom Functions, Post-Call
 * Analysis, Webhook URL) or send to Retell's create-LLM / create-agent API; the
 * field names follow Retell's API. `docs/receptionist/agent.json` is this
 * output for the production origin, regenerated by the dry-run test.
 */
export function agentPrompt(): string {
  const r = receptionist;
  return [
    ...r.role,
    "",
    "## The call",
    ...r.flow,
    "",
    "## Never",
    ...r.never.map((line) => `- ${line}`),
    "",
    r.servicesIntro,
    ...services.map((s) => `- ${s.name}: ${s.promise}`),
  ].join("\n");
}

export function retellAgentConfig(origin: string) {
  const r = receptionist;
  const tool = (path: string) => `${origin}/api/voice/${path}`;
  return {
    llm: {
      begin_message: r.greeting,
      general_prompt: agentPrompt(),
      general_tools: [
        {
          type: "custom",
          name: r.tools.checkSlots.name,
          description: r.tools.checkSlots.description,
          url: tool("tools"),
          speak_during_execution: false,
          speak_after_execution: true,
          parameters: { type: "object", properties: {} },
        },
        {
          type: "custom",
          name: r.tools.book.name,
          description: r.tools.book.description,
          url: tool("tools"),
          speak_during_execution: false,
          speak_after_execution: true,
          parameters: {
            type: "object",
            properties: Object.fromEntries(
              Object.entries(r.tools.book.params).map(([key, description]) => [key, { type: "string", description }]),
            ),
            required: ["start", "name"],
          },
        },
        { type: "end_call", name: "end_call", description: "End the call after saying goodbye, or when the caller is abusive." },
      ],
    },
    agent: {
      webhook_url: tool("post-call"),
      post_call_analysis_data: [
        { type: "string", name: "caller_name", description: "The caller's name, if they gave it." },
        { type: "string", name: "business", description: "The caller's business name, if they gave it." },
        { type: "string", name: "reason", description: "What the caller needs, in one short sentence." },
      ],
    },
  };
}
